// dist = {0, INF, INF, INF}
boolean[] done = new boolean[n];
pq.offer(new int[]{0, 0});                     // {dist, node}
while (!pq.isEmpty()) {
    int u = pq.poll()[1];
    if (done[u]) continue;
    done[u] = true;                            // finalised
    for (int[] e : adj.get(u)) {               // e = {v, w}
        int v = e[0], w = e[1];
        if (!done[v] && dist[u] + w < dist[v]) {
            dist[v] = dist[u] + w;
            pq.offer(new int[]{dist[v], v});
        }
    }
}

boolean hasCycle(int u, List<List<Integer>> adj, boolean[] vis) {
    vis[u] = true;
    for (int v : adj.get(u)) {
        if (vis[v]) return true;
        if (hasCycle(v, adj, vis)) return true;
    }
    return false;
}

void dfs(int u, int parent) {
    tin[u] = low[u] = ++timer;
    for (int v : adj.get(u)) {
        if (v == parent) continue;
        if (tin[v] == 0) {                     // tree edge
            dfs(v, u);
            low[u] = Math.min(low[u], low[v]);
            if (low[v] > tin[u]) bridges.add(u + "-" + v);
        } else low[u] = Math.min(low[u], tin[v]);   // back edge
    }
}

